import { tags } from "typia";

/**
 * Comprehensive statistical overview of comment activity across the entire
 * discussion board platform, including total comment metrics, reply patterns,
 * vote sentiment, report volumes, moderator actions, and notification rates.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDiscussionBoardCommentOverview = {
  /**
   * Total number of comments across the entire discussion board platform.
   * This includes all comments on articles and replies within comment
   * threads.
   */
  total_comments: number & tags.Type<"int32">;

  /**
   * Total number of reply comments (nested comments) in the discussion board.
   * This measures the depth of conversation threads initiated by primary
   * comments.
   */
  total_replies: number & tags.Type<"int32">;

  /**
   * Average sentiment score of comments based on upvotes minus downvotes. A
   * positive value indicates overall positive engagement, while negative
   * indicates negative sentiment. Calculated as the mean difference between
   * up_votes and down_votes across all comments.
   */
  avg_sentiment: number;

  /**
   * Total number of user reports submitted against comments. This metric
   * tracks community moderation efforts and identifies potentially
   * problematic content across the platform.
   */
  total_reports: number & tags.Type<"int32">;

  /**
   * Total number of moderation actions taken by moderators in response to
   * reports. This includes actions such as removing comments, issuing
   * warnings, or suspending users based on reported violations.
   */
  mod_actions_taken: number & tags.Type<"int32">;

  /**
   * Total number of system-generated notifications sent to users regarding
   * comment activity, including replies, mentions, and report outcomes.
   */
  notifications_sent: number & tags.Type<"int32">;
};
